import{_ as a,o as e,c as n,a2 as o}from"./chunks/framework.D9E58p8B.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{"title":"Installation"},"headers":[],"relativePath":"en/guide/installation.md","filePath":"en/guide/installation.md"}'),i={name:"en/guide/installation.md"};function r(l,t,s,d,h,c){return e(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>The files are in the <a href="https://github.com/ArboRithm/Daimon/releases/latest" target="_blank" rel="noreferrer">latest release</a>.</p><table tabindex="0"><thead><tr><th>Platform</th><th>Requirements</th><th>File</th></tr></thead><tbody><tr><td>macOS</td><td>Apple Silicon, macOS 12 or later</td><td><code>Daimon_&lt;version&gt;_aarch64.dmg</code></td></tr><tr><td>Windows</td><td>Windows 10 version 2004 or later, x64</td><td><code>Daimon_&lt;version&gt;_x64-setup.exe</code></td></tr><tr><td>Windows (preview)</td><td>Windows 10 version 2004 or later, ARM64</td><td><code>Daimon_&lt;version&gt;_arm64-setup.exe</code></td></tr></tbody></table><p>The macOS build is signed and notarized by Apple. Windows ARM64 support is a preview: it has not yet been tested on a real ARM machine.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p><strong>Install before registering your AI clients</strong>: they are registered with the application&#39;s location.</p><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>Open the DMG and drag Daimon into <strong>Applications</strong>.</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>Run the installer. It is Authenticode-signed, and the publisher shown is ArboRithm. If SmartScreen still shows a warning, click <strong>More info</strong>, then <strong>Run anyway</strong>.</p><p>Once installed, the program is at <code>%LOCALAPPDATA%\\Daimon\\Daimon.exe</code>.</p><h2 id="first-launch" tabindex="-1">First launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First launch&quot;">​</a></h2><ol><li>Launch Daimon. It lives in the menu bar on macOS (no Dock icon) and in the notification area on Windows, near the clock, possibly in the overflow menu.</li><li>Click its icon to open the <strong>panel</strong>.</li><li>Choose <strong>Relancer l&#39;installation…</strong> (Re-run setup…): the walkthrough guides you through the permissions (on macOS) and your AI clients.</li><li><strong>Restart your AI client</strong>, then ask it to look at your screen.</li></ol><p>Next: <a href="./autorisations.html">Permissions</a>.</p>',15)])])}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
